68	func createFixedResourceConfig(cfg *ResourceConfig, res *pcommon.Resource) (*otelconf.Resource, error) {
69		if res == nil {
70			return nil, errMissingCollectorResource
71		}
72	
73		providerConfig := &otelconf.Resource{
74			Attributes: make([]otelconf.AttributeNameValue, 0, res.Attributes().Len()),
75		}
76		if cfg.SchemaUrl != nil {
77			// Preserve the configured schema URL separately because it is not exposed by pcommon.Resource.
78			schemaURL := *cfg.SchemaUrl
79			providerConfig.SchemaUrl = &schemaURL
80		}
