94		ctx context.Context,
95		set telemetry.Settings,
96		componentConfig component.Config,
97	) (pcommon.Resource, error) {
98		sdkCfg, err := createInitialResourceConfig(set.BuildInfo, &componentConfig.(*Config).Resource)
99		if err != nil {
100			return pcommon.Resource{}, err
101		}
102	
103		sdk, err := otelconf.NewSDK(otelconf.WithContext(ctx), otelconf.WithOpenTelemetryConfiguration(otelconf.OpenTelemetryConfiguration{
104			Resource: sdkCfg,
105		}))
106		if err != nil {
107			return pcommon.Resource{}, err
108		}
109	
110		sdkResource := sdk.Resource()
111		sdkIterator := sdkResource.Iter()
112	
113		pcommonResource := pcommon.NewResource()
